import{_ as t,d as a,e as o,y as n}from"./chunks/framework.D7CAgLCq.js";const u=JSON.parse('{"title":"Toyota Andon: what happens after an abnormality becomes visible?","description":"A published process links a signal to response; implementation and lasting learning require further evidence.","frontmatter":{"title":"Toyota Andon: what happens after an abnormality becomes visible?","description":"A published process links a signal to response; implementation and lasting learning require further evidence.","kind":"Documented process","source_type":"Corporate process descriptions and history"},"headers":[],"relativePath":"en/cases/toyota-andon.md","filePath":"en/cases/toyota-andon.md"}'),s={name:"en/cases/toyota-andon.md"};function i(r,e,l,c,p,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="toyota-andon-what-happens-after-an-abnormality-becomes-visible" tabindex="-1">Toyota Andon: what happens after an abnormality becomes visible? <a class="header-anchor" href="#toyota-andon-what-happens-after-an-abnormality-becomes-visible" aria-label="Permalink to &quot;Toyota Andon: what happens after an abnormality becomes visible?&quot;">​</a></h1><p>A visible warning can be a notification or part of an operational response. Toyota’s public factory explanation describes workers using a call button when they find a problem, an Andon display notifying the person in charge, and work resuming after resolution. This is the company’s account of its own process.</p><h2 id="the-connections-differ-by-process" tabindex="-1">The connections differ by process <a class="header-anchor" href="#the-connections-differ-by-process" aria-label="Permalink to &quot;The connections differ by process&quot;">​</a></h2><p>Toyota’s <a href="https://global.toyota/en/company/vision-and-philosophy/production-system/" target="_blank" rel="noreferrer">production-system explanation</a> distinguishes equipment stopping on an abnormality and then signaling staff from assembly work without equipment, where pulling a stop cord can light an Andon and call a supervisor. A light does not have one universal relationship to immediate machine stoppage. The actual links among detection, display, stopping, response, and resumption must be read in their specific setting.</p><p>The company’s historical account records that in 1955 the Crown assembly line at the Honsha plant introduced an Andon linked to stop buttons so that the process causing a line stop could be identified. This documents a stated equipment/process connection, not a measured effect across all later factories.</p><h2 id="read-the-process-through-effective-feedback" tabindex="-1">Read the process through effective feedback <a class="header-anchor" href="#read-the-process-through-effective-feedback" aria-label="Permalink to &quot;Read the process through effective feedback&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/en/theory/part-03.html#section-3-3">§3.3</a> asks what earlier state or output returns, through what channel, to which receiving position, and what subsequent item it changes. A signal’s visibility answers only part of that inquiry. In the process description, the useful next question is how the signal changes response and the conditions for continuing work.</p><p>The sources support an account of the published arrangement. They do not by themselves estimate the proportion of calls handled correctly, response times at a particular facility, or the independent causal contribution of Andon to quality. Those claims need appropriate observations and comparisons for a declared site, period, and task.</p><h2 id="handling-one-problem-does-not-finish-the-learning-question" tabindex="-1">Handling one problem does not finish the learning question <a class="header-anchor" href="#handling-one-problem-does-not-finish-the-learning-question" aria-label="Permalink to &quot;Handling one problem does not finish the learning question&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-3">§6.3</a> distinguishes feedback from feedback-mediated learning. To support the latter, follow an update into a carrier, examine its retention and actual use in later rounds, and compare the specified task outcome. A successful detection–response–resumption sequence does not alone establish lasting learning, general transfer, or a positive net outcome.</p><p>The same distinction protects partial achievements. An effective response to one abnormality need not be dismissed because evidence of longer-term learning is absent. State what the material actually supports and leave the additional claim open.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li>Toyota, <a href="https://global.toyota/en/company/plant-tours/production-system/" target="_blank" rel="noreferrer">Virtual Plant Tour: Toyota Production System</a>.</li><li>Toyota, <a href="https://global.toyota/en/company/vision-and-philosophy/production-system/" target="_blank" rel="noreferrer">Toyota Production System</a>.</li><li>Toyota, <a href="https://www.toyota-global.com/company/history_of_toyota/75years/common/pdf/production_system.pdf" target="_blank" rel="noreferrer">75-Year History: production-system chronology</a>, 1955 entry.</li></ul><p>These corporate sources are not independent impact evaluations. Continue with <a href="./../concepts/feedback.html">feedback</a>, <a href="./../concepts/history.html">history and learning</a>, or <a href="./../concepts/responsibility.html">responsibility</a>.</p>',14)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
